#include <WiFi.h>

const char* NAMES[10] = {
  "8Б СУКИ",
  "8Б ДАЛБАЁБЫ",
  "8Б ДАУНЫ",
  "8Б ШАЛАВЫ",
  "8Б ПЕДИКИ",
  "8Б СОСУТСА",
  "8Б ПИДАРАСЫ",
  "8Б ХУЕСОСЫ",
  "8Б ШЛЮХИ",
  "8Б ГЕИ"
};

const int NAMES_COUNT = 10;
const int CHANNEL = 1;
const unsigned long RENAME_INTERVAL = 250;

#define BOOT_PIN 0   // кнопка BOOT на всех платах ESP32 — GPIO 0

unsigned long lastRename = 0;
int currentName = 0;
bool wifiOn = true;
bool lastButton = HIGH;

void setup() {
  Serial.begin(115200);

  pinMode(BOOT_PIN, INPUT_PULLUP);

  WiFi.mode(WIFI_AP);
  WiFi.softAP(NAMES[0], nullptr, CHANNEL);
  Serial.println("Точка доступа запущена, начинаю смену имён...");
}

void loop() {
  // нажатие кнопки BOOT: короткое нажатие включает/выключает сети
  bool btn = digitalRead(BOOT_PIN);
  if (lastButton == HIGH && btn == LOW) {
    wifiOn = !wifiOn;

    if (wifiOn) {
      WiFi.mode(WIFI_AP);
      WiFi.softAP(NAMES[currentName], nullptr, CHANNEL);
      Serial.println("Сети ВКЛ");
    } else {
      WiFi.softAPdisconnect(true);
      WiFi.mode(WIFI_OFF);
      Serial.println("Сети ВЫКЛ");
    }

    delay(300);  // защита от дребезга
  }
  lastButton = btn;

  // смена имени — только пока сети включены
  if (wifiOn && millis() - lastRename >= RENAME_INTERVAL) {
    lastRename = millis();

    currentName = (currentName + 1) % NAMES_COUNT;
    WiFi.softAP(NAMES[currentName], nullptr, CHANNEL);
  }
}
